(789728, 86941, 22619, '<td valign="top">cropped a little tight for me, but an interesting shot none the less. makes me wonder about the rest of the boat.</td>', 'cropped a little tight for me, but an interesting shot none the less. makes me wonder about the rest of the boat.', '2004-07-01 10:49:30.000000', NULL, 1),
(789729, 85784, 22619, '<td valign="top">Nice shot</td>', 'Nice shot', '2004-07-01 10:50:34.000000', NULL, 1),
